<?php ob_start(); ?><h1>Signature #<?= e($signature['id']??'') ?></h1><?php if(!$signature): ?><p>Not found.</p><?php else: ?><div class="card"><p><b>Name:</b> <?= e($signature['name']) ?> <b>Risk:</b> <?= e($signature['risk']) ?> <b>Source:</b> <?= e($signature['source']) ?></p><p><?= e($signature['description']) ?></p><pre><?= e(json_encode(json_decode($signature['pattern_json']?:'{}', true), JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre><form method="post" action="/signatures/test"><input type="hidden" name="id" value="<?= e($signature['id']) ?>"><input class="input" name="file_path" placeholder="File path"><button class="btn">Test against file</button></form><?php if(isset($test)): ?><pre><?= e(json_encode($test, JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre><?php endif ?></div><div class="card"><h2>Recent matches</h2><table><?php foreach($matches as $m): ?><tr><td><a href="/findings/<?= e($m['id']) ?>">#<?= e($m['id']) ?></a></td><td><?= e($m['risk']) ?></td><td><code><?= e($m['path']) ?></code></td></tr><?php endforeach ?></table></div><?php endif ?><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>